import {Text} from '@primer/react-brand'
import {CheckCircle} from './CheckCircle'
import {NumberCircle} from './NumberCircle'

import styles from './StaticSignupStep.module.css'

interface StaticSignupsStep {
  stepIndex: number
  bulletText: string
  isCompleted?: boolean
}

export const StaticSignupStep = ({stepIndex, bulletText, isCompleted = false}: StaticSignupsStep) => {
  return (
    <div className={styles.stepContainer}>
      <span className="mb-1">{isCompleted ? <CheckCircle /> : <NumberCircle number={stepIndex + 1} />}</span>
      <span className={styles.stepText}>
        <Text size="100">{bulletText}</Text>
      </span>
    </div>
  )
}
