import {documentToReactComponents} from '@contentful/rich-text-react-renderer'
import {BLOCKS, INLINES} from '@contentful/rich-text-types'
import {InlineLink, Text, UnorderedList} from '@primer/react-brand'
import {BulletStyle, type BulletStyle as BulletStyleType} from '../lib/types/bullet-style'
import type {RichContentSchema as RichContentSchemaType} from '../lib/types/contentful/rich-content-schema'

import css from './ContentfulContentBlock.module.css'

type ContentfulContentBlockProps = {
  text: RichContentSchemaType['fields']['text']
  bulletStyle?: BulletStyleType
  terms?: boolean
}

export const ContentfulContentBlock = ({
  text,
  bulletStyle = BulletStyle.default,
  terms = false,
}: ContentfulContentBlockProps): React.ReactNode => {
  return documentToReactComponents(text, {
    renderNode: {
      [BLOCKS.PARAGRAPH]: (_, children) => (
        <Text
          as="p"
          size="100"
          className="mb-2"
          variant={terms ? 'muted' : 'default'}
          data-testid={terms ? 'terms-text' : 'default-text'}
        >
          {children}
        </Text>
      ),
      [BLOCKS.UL_LIST]: (_, children) => (
        <UnorderedList variant={bulletStyle} data-testid={'unordered-list'} className={css.ulList}>
          {children}
        </UnorderedList>
      ),
      [BLOCKS.LIST_ITEM]: (_, children) => {
        return (
          <UnorderedList.Item>
            <Text size="100">{children}</Text>
          </UnorderedList.Item>
        )
      },
      [INLINES.HYPERLINK]: (node, children) => {
        return <InlineLink href={node.data.uri}>{children}</InlineLink>
      },
    },
  })
}
